{id:95,question:"Which Australian National Railway line runs across the country from west to east?",options:{A:"The Perth-Sydney line (West-East Australian National Railway line)",B:"The Darwin-Melbourne Trans-Continental line",C:"The Brisbane-Adelaide Coastal railway",D:"The Great Barrier Reef Express"},answer:"A",explanation:"",chapter:"",topic:""},
{id:96,question:"Where are New Zealand’s railways mainly located?",options:{A:"In the South Island to serve the rugged mining regions",B:"In the North Island to serve the farming areas",C:"Along the narrow coastal strips of both islands equally",D:"Connecting Wellington directly to Christchurch via an undersea tunnel"},answer:"B",explanation:"",chapter:"",topic:""},
{id:97,question:"In South America, where is the rail network most dense?",options:{A:"In the Amazon rainforest basin and the high Andes peaks",B:"In the Pampas of Argentina and the coffee growing region of Brazil (accounting for 40% of South America's total route length)",C:"Along the northern Caribbean coastline from Venezuela to Colombia",D:"Throughout the southern Patagonian ice fields"},answer:"B",explanation:"",chapter:"",topic:""},
{id:98,question:"Aside from Argentina and Brazil, which South American country has a considerable route length linking coastal centres with interior mining sites?",options:{A:"Peru",B:"Chile",C:"Bolivia",D:"Paraguay"},answer:"B",explanation:"",chapter:"",topic:""},
{id:99,question:"How are the rail lines characterized in Peru, Bolivia, Ecuador, Colombia, and Venezuela?",options:{A:"They form an extensive, highly interconnected continental grid.",B:"They are high-speed multi-tracked commuter networks.",C:"They are short single-track rail-lines from ports to the interior with no inter-connecting links.",D:"They are exclusively underground electric metro systems."},answer:"C",explanation:"",chapter:"",topic:""},
{id:100,question:"How many trans-continental rail routes exist in South America, and what do they connect?",options:{A:"Two routes connecting Rio de Janeiro to Lima and Quito",B:"Only one trans-continental rail route linking Buenos Aires (Argentina) with Valparaiso (Chile) across the Andes Mountains through the Uspallatta Pass (at 3,900 m height)",C:"Three routes connecting the Atlantic coast to the Pacific coast across the Amazon",D:"No trans-continental rail routes exist in South America at all"},answer:"B",explanation:"",chapter:"",topic:""}
